INSERT INTO src_pres (id, nome, foto, descricao, propostas) VALUES 
(1, 'Dércia Guambe', 'pic/pr/dercia.jpg', 'Líder visionária com vasta experiência em gestão de projetos cívicos.', 'Digitalização total dos processos académicos, maior transparência financeira e criação de bolsas de apoio.'),
(2, 'Dalton Nhambio', 'pic/pr/dalton.jpg', 'Engenheiro focado em inovação tecnológica e otimização de infraestruturas.', 'Melhoria da rede de Wi-Fi no campus, otimização dos laboratórios e suporte a startups estudantis.'),
(3, 'Cristêncio Cristiano', 'pic/pr/cris.jpg', 'Defensor dos direitos dos estudantes.', 'Criação de cantinas acessíveis, espaços de estudo abertos 24h'),
(4, 'Néima Filomena', 'pic/pr/neima.jpg', 'Especialista em comunicação institucional.', 'Fóruns mensais abertos com a reitoria, maior rigor na atribuição de subsídios e desporto inclusivo.');
INSERT INTO src_sec (id, nome, foto, descricao, propostas) VALUES 
(1, 'Credson de Sousa', 'pic/sc/credson.jpg', 'Organizado e rigoroso na gestão documental e secretariado.', 'Desburocratização de requerimentos online e atendimento automatizado.'),
(2, 'Ginalda Vilanculos', 'pic/sc/ginalda.jpg', 'Especialista em organização de arquivos e atendimento rápido.', 'Redução do tempo de resposta de documentos para 24 horas e arquivo digital seguro.'),
(3, 'Birlêndio Artur', 'pic/sc/birlendio.jpg', 'Eficiência administrativa e suporte ao estudante.', 'Plataformas para pedidos de declarações e certificados.'),
(4, 'Binélvia Pololo', 'pic/sc/binelvia.jpg', 'Inovação nos fluxos de trabalho administrativos.', 'Atendimento via chat integrado e desmaterialização total de impressos.');
INSERT INTO src_est (id, nome, foto, descricao, propostas) VALUES 
